import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.iXqqCa-C.js";const i="/images/agent-create-regex.webp",s="/images/agent-create-stickers.webp",_=JSON.parse('{"title":"正则与表情包","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/regex-stickers.md","filePath":"guide/agent/regex-stickers.md","lastUpdated":1793029602000}'),n={name:"guide/agent/regex-stickers.md"};function l(c,a,d,g,h,p){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="正则与表情包" tabindex="-1">正则与表情包 <a class="header-anchor" href="#正则与表情包" aria-label="Permalink to &quot;正则与表情包&quot;">​</a></h1><p>角色编辑页的「正则」和「表情包」两个部分：正则对消息内容做过滤，表情包让角色发送专属贴纸。</p><h2 id="正则" tabindex="-1">正则 <a class="header-anchor" href="#正则" aria-label="Permalink to &quot;正则&quot;">​</a></h2><p>对匹配到的用户消息或 AI 输出应用过滤。原始消息仍会保留，编辑消息时显示完整内容。</p><p><img src="'+i+'" alt="正则"></p><h3 id="规则字段" tabindex="-1">规则字段 <a class="header-anchor" href="#规则字段" aria-label="Permalink to &quot;规则字段&quot;">​</a></h3><ul><li><strong>正则表达式</strong>：JavaScript 正则语法，匹配到的内容会被删除。语法错误会提示无效。</li><li><strong>作用对象</strong>（可多选）：用户消息 / AI 输出。</li><li><strong>作用效果</strong>（可多选）： <ul><li><strong>不显示</strong>：用户端看不到匹配内容。</li><li><strong>AI 看不见</strong>：匹配内容不会发给模型。</li></ul></li></ul><p>两个效果可以同时勾选，也可以只勾一个。例如只勾「不显示」时，用户看不到匹配内容，模型仍能读到。</p><h3 id="测试预览" tabindex="-1">测试预览 <a class="header-anchor" href="#测试预览" aria-label="Permalink to &quot;测试预览&quot;">​</a></h3><p>选择测试消息类型（用户消息 / AI 输出）并输入测试文本，按当前<strong>未保存</strong>的规则同时预览「用户端显示」和「发送给 AI」两种结果。</p><h2 id="角色表情包" tabindex="-1">角色表情包 <a class="header-anchor" href="#角色表情包" aria-label="Permalink to &quot;角色表情包&quot;">​</a></h2><p>角色专属贴纸，角色根据描述在合适的时机发送。贴纸单独成行显示为方形图块，开启分段输出时独占一个气泡。</p><p><img src="'+s+'" alt="表情包"></p><h3 id="添加表情包" tabindex="-1">添加表情包 <a class="header-anchor" href="#添加表情包" aria-label="Permalink to &quot;添加表情包&quot;">​</a></h3><p>每个角色最多 50 个，每个包含：</p><ul><li><strong>标识（key）</strong>：1-32 位，仅字母、数字、下划线和短横线，角色内唯一，用于语法 <code>[[agent_sticker key=标识]]</code>。</li><li><strong>描述（必填）</strong>：模型据此判断使用时机，留空无法保存。</li><li><strong>图片</strong>：任意比例的图片或动图，不超过 5MiB。</li></ul><p><strong>AI 生成描述</strong>：由识图模型看图生成描述，可单个生成，也可「为未填描述的批量生成」。费用按识图模型单价从你的余额扣除。</p><h3 id="会话中的表情设置" tabindex="-1">会话中的表情设置 <a class="header-anchor" href="#会话中的表情设置" aria-label="Permalink to &quot;会话中的表情设置&quot;">​</a></h3><ul><li><strong>启用智能体表情包</strong>：总开关。开启后用户与角色都可以发全站表情，角色还能按描述选择全站表情和专属贴纸。</li><li><strong>每轮表情包上限</strong>：单条回复中全站表情与贴纸合计的上限（0-10，0 为关闭），超出部分自动移除。</li></ul><p>角色能选用哪些全站自定义表情，取决于管理员是否为该表情填写了「智能体描述」。</p><h2 id="使用语法" tabindex="-1">使用语法 <a class="header-anchor" href="#使用语法" aria-label="Permalink to &quot;使用语法&quot;">​</a></h2><p>对话里表情的书写方式见<a href="/guide/agent/syntax#表情与贴纸">对话语法</a>：全站表情用 <code>:名字:</code>，角色贴纸由角色以 <code>[[agent_sticker key=标识]]</code> 语法发出。</p>',22)])])}const m=e(n,[["render",l]]);export{_ as __pageData,m as default};
